// Guides are grouped by topic here (test/sidebars.test.mjs checks that every guide in docs/guides is listed once);
// the Reference tree is generated by `npm run apidocs` (.generated/sidebar.json), grouped by namespace and area; so are
// the Samples (.generated/sidebar-samples.json), one entry per category, then the samples by API; the samples
// themselves are listed on those pages. Without a fetched samples index there is no Samples category.
const { existsSync, readFileSync } = require('node:fs');

const generated = (file) => (existsSync(file) ? JSON.parse(readFileSync(file, 'utf8')) : []);
const reference = generated('./.generated/sidebar.json');
const samples = existsSync('./docs/samples/index.md') ? generated('./.generated/sidebar-samples.json') : [];

const group = (label, docs, collapsed = true) => ({
  type: 'category',
  label,
  collapsible: true,
  collapsed,
  items: docs.map((doc) => `guides/${doc}`),
});

const guides = [
  'guides/getting-started',
  group('Building an extension', ['project-setup', 'runtime-and-hosting', 'development-loop', 'api-conventions', 'interfaces-at-run-time']),
  group('User interface', ['menus', 'messages-panel', 'panels']),
  group('Design data', ['schematic-basics', 'pcb-basics', 'bom', 'design-data-notes']),
  group('Outputs and services', ['outputers', 'altium-365-api']),
  'guides/gotchas',
];

module.exports = {
  docs: [
    'index',
    {
      type: 'category',
      label: 'Guides',
      collapsible: false,
      items: guides,
    },
    {
      type: 'category',
      label: 'Reference',
      collapsible: false,
      link: existsSync('./docs/reference/index.md') ? { type: 'doc', id: 'reference/index' } : undefined,
      items: reference,
    },
    ...(samples.length
      ? [{ type: 'category', label: 'Samples', className: 'section-link', collapsible: true, collapsed: true, link: { type: 'doc', id: 'samples/index' }, items: samples }]
      : []),
  ],
};
